def _encrypt_val(v):
    if v is None:
        return None
    s = str(v)
    if _FERNET:
        try:
            return _FERNET.encrypt(s.encode()).decode()
        except Exception:
            return None
    return s


def _decrypt_val(v):
    if v is None:
        return None
    if _FERNET:
        try:
            return _FERNET.decrypt(v.encode()).decode()
        except Exception:
            # Fallback: if decryption fails, assume it's unencrypted (legacy/corrupted data) and return as-is
            return v
    return v

def resolve_logs_dir() -> Path:
    """Determine which logs directory to use (env override > VM path > local logs)."""
    env_dir = os.environ.get("MINTZY_LOGS_DIR")
    if env_dir:
        return Path(env_dir)
    if VM_LOGS_DIR.exists():
        return VM_LOGS_DIR
    return DEFAULT_LOGS_DIR

