@app.get("/api/admin/trading-logs")
async def fetch_all_trading_logs(
    limit: int = 500,
    x_plugin_api_key: str = Header(None)
):
# verify_plugin_key(x_plugin_api_key)

    if not DB_CONNECTED:
        raise HTTPException(status_code=500, detail="DB not connected")

    limit = max(1, min(limit, 2000))

    cursor = (
        trading_logs_collection
        .find({}, {"_id": 0})
        .sort("timestamp", -1)
        .limit(limit)
    )

    logs = []
    for doc in cursor:
        if isinstance(doc.get("timestamp"), datetime):
            doc["timestamp"] = doc["timestamp"].isoformat()
        logs.append(doc)

    return {
        "success": True,
        "count": len(logs),
        "logs": logs
    }

