@app.get("/api/debug/insert-fake-trades/{session_id}")
def debug_insert_fake_trades(session_id: str):
    """
    DEBUG ONLY:
    Inserts fake trading snapshots into MongoDB
    without running AutoTrader or broker.
    """

    fake_cycles = 3
    symbols = ["RELIANCE", "TCS", "INFY"]

    for cycle in range(1, fake_cycles + 1):
        rows = []

        for sym in symbols:
            rows.append({
                "symbol": sym,
                "curr_price": round(random.uniform(1000, 3000), 2),
                "return_pct": round(random.uniform(-2, 2), 4),
                "side": random.choice(["BUY", "SELL", "NONE"]),
                "signal": random.choice(["BUY", "SELL", "HOLD", "STOP-LOSS"]),
                "action": random.choice(["OPEN", "HOLD", "CLOSE"]),
                "unrealized_pnl": round(random.uniform(-500, 500), 2),
            })

        snapshot = {
            "cycle": cycle,
            "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "cash_balance": 100000.0,
            "realized_pnl": round(random.uniform(-2000, 2000), 2),
            "unrealized_pnl": round(random.uniform(-1000, 1000), 2),
            "total_equity": 100000.0,
            "symbols": rows,
        }

        insert_trading_snapshot(
            trading_logs_collection=trading_logs_collection,
            session_id=session_id,
            cycle=cycle,
            snapshot=snapshot,
            rows=rows,
        )

    return {
        "success": True,
        "message": "Fake trading logs inserted",
        "session_id": session_id,
        "cycles": fake_cycles,
        "symbols": symbols,
    }
    
# it is being polled to fetch whether the snapshot is ready or not 
# and if it is ready it updates the ui
@app.get("/api/trading/snapshot/{session_id}")
def get_trading_snapshot(session_id: str ,x_plugin_api_key: str = Header(None)):

    # verify_plugin_key(x_plugin_api_key)
    snap = trading_snapshot.get(session_id)
    # print("fetching snapshot for session_id",session_id)

    if not snap:
        return {
            "success": True,
            "ready": False,
            "message": "Snapshot initializing"
        }
    

    # print("snapshot found for session_id",session_id)
    # print("snapshot data:",snap)

    return {
        "success": True,
        "ready": True,
        "data": snap
    }


@app.get("/api/trading/live-pnl/{session_id}")
def get_live_pnl(session_id: str, x_plugin_api_key: str = Header(None)):
    """
    Returns tick-by-tick PnL for a running session.
    Data is written to Redis by the trader's on_ltp_tick() at most once per second.
    TTL is 5s — if the key is missing the trader is not running or WS is down.
    """
    if not _rms_redis:
        return {"success": False, "error": "Redis unavailable"}

    try:
        raw = _rms_redis.get(f"live_pnl:{session_id}")
    except Exception as e:
        return {"success": False, "error": f"Redis error: {e}"}

    if not raw:
        return {
            "success": True,
            "ready": False,
            "message": "No live PnL data yet — trader may not be running or WS not connected",
        }

    try:
        data = json.loads(raw)
    except Exception:
        return {"success": False, "error": "Malformed payload in Redis"}

    return {"success": True, "ready": True, "data": data}


