# previous function to downlaod the live_data.csv file should not be used 
@app.get("/api/dashboard/live-data/download")
def download_live_data():
    file_path = LOGS_DIR / "live_data.csv"

    if not file_path.exists():
        raise HTTPException(status_code=404, detail="Live data not available")

    return FileResponse(
        path=file_path,
        filename="live_data.csv",
        media_type="text/csv",
    )

  
