async def get_or_restore_session(session_id: str) -> Optional[Dict[str, Any]]:
    """
    Robust session retrieval that handles multi-worker synchronization.
    1. Checks in-memory store.
    2. If in-memory is missing OR stale (not authenticated), checks DB.
    3. If DB has authenticated session, restores it into memory.
    """
    print(f"[SYNC-DEBUG] get_or_restore_session called for {session_id}")
    session_data = sessions_store.get(session_id)
    print(f"[SYNC-DEBUG] Local RAM status: {session_data.get('status') if session_data else 'None'}")
    
    # Fast path: If RAM has it and it's authenticated, return immediately
    if session_data and session_data.get("status") == "authenticated":
        # Additional safety: ensure broker object exists
        if session_data.get("broker") and session_data.get("broker_session"):
            if session_data.get("configuration_id") is None and DB_CONNECTED:
                db_session = await fetch_session_from_db(session_id)
                if db_session and db_session.get("configuration_id"):
                    session_data["configuration_id"] = db_session.get("configuration_id")
                    sessions_store[session_id] = session_data
            return session_data

    # Slow path: Fetch from DB if we can
    if not DB_CONNECTED:
        print("[SYNC-DEBUG] DB not connected, returning local data")
        return session_data

    # logger.info(f"[{session_id}] Checking DB for session sync (Local status: {session_data.get('status') if session_data else 'None'})")
    print(f"[SYNC-DEBUG] Fetching from DB for {session_id}")
    db_session = await fetch_session_from_db(session_id)
    
    if not db_session:
        print("[SYNC-DEBUG] Session not found in DB")
        return session_data

    db_status = db_session.get("status")
    print(f"[SYNC-DEBUG] DB status: {db_status}")
    
    broker_session_db = db_session.get("broker_session")
    db_has_stored_auth = (
        db_session.get("api_key")
        and db_session.get("client_code")
        and db_session.get("password")
        and broker_session_db
        and (
            db_status == "authenticated"
            or db_session.get("authenticated_at")
        )
    )

    # If DB has auth tokens, restore when local RAM is missing or stale.
    if db_has_stored_auth:
            
            try:
                # logger.info(f"[{session_id}] Restoring broker session from DB...")
                
                # Set env vars for BrokerConnector (it reads from env or args)
                # But here we can pass args directly if we modify BrokerConnector or just set env
                # The existing code mostly relies on env vars or direct init.
                # Let's check how BrokerConnector is initialized in the file.
                # It seems it takes no args in __init__ usually, or maybe it does?
                # Looking at line 1346: res_broker = BrokerConnector(require_totp=False)
                # Looking at line 1450: broker = BrokerConnector(require_totp=False)
                # It seems it relies on os.environ being set OR maybe it doesn't need them for `restore_session`?
                # Wait, `restore_session` needs the tokens. `get_account_balance` needs the instance.
                # To be safe, let's set env vars temporarily like the other functions do, 
                # OR check if BrokerConnector accepts args. 
                # The previous code set env vars. Let's stick to that pattern for safety.
                
                os.environ["ANGEL_API_KEY"] = db_session["api_key"]
                os.environ["ANGEL_CLIENT_CODE"] = db_session["client_code"]
                os.environ["ANGEL_PASSWORD"] = db_session["password"]
                
                broker = BrokerConnector(require_totp=False)
                
                restored_session = broker.restore_session({
                    "token": broker_session_db.get("token"),
                    "refresh_token": broker_session_db.get("refresh_token"),
                    "feed_token": broker_session_db.get("feed_token"),
                })
                
                # Cleanup env
                for key in ["ANGEL_API_KEY", "ANGEL_CLIENT_CODE", "ANGEL_PASSWORD"]:
                    if key in os.environ:
                        del os.environ[key]

                if restored_session and restored_session.get("token"):
                    # Success! Update sessions_store
                    sessions_store[session_id] = {
                        "session_id": session_id,
                        "api_key": db_session.get("api_key"),
                        "client_code": db_session.get("client_code"),
                        "password": db_session.get("password"),
                        "status": "authenticated",
                        "free_cash": db_session.get("free_cash"),
                        "broker_session": restored_session,
                        "broker": broker,
                        "authenticated_at": db_session.get("authenticated_at"),
                        "created_at": db_session.get("created_at"),
                        "user_id": db_session.get("user_id"),
                        "configuration_id": db_session.get("configuration_id"),
                    }
                    print("[SYNC-DEBUG] Successfully restored session from DB and updated RAM")
                    return sessions_store[session_id]
            except Exception as e:
                print(f"[SYNC-DEBUG] Exception during restoration: {e}")
                logger.error(f"[{session_id}] Failed to restore session from DB: {e}")
                
    # If we are here, we couldn't restore broker from DB tokens.
    # Populate RAM from DB when local is missing or clearly stale vs persisted auth markers.
    local_stale = (
        not session_data
        or (
            session_data.get("status") != "authenticated"
            and db_has_stored_auth
        )
    )
    if local_stale and db_session:
         # Restore all serializable fields so subsequent steps (like totp) can use them
         sessions_store[session_id] = {
            "session_id": session_id,
            "status": "authenticated" if db_has_stored_auth else db_session.get("status"),
            "created_at": db_session.get("created_at"),
            "api_key": db_session.get("api_key"),
            "client_code": db_session.get("client_code"),
            "password": db_session.get("password"),
            "user_id": db_session.get("user_id"),
            "free_cash": db_session.get("free_cash"),
            "broker_session": db_session.get("broker_session"),
            "authenticated_at": db_session.get("authenticated_at"),
            "configuration_id": db_session.get("configuration_id"),
         }
         return sessions_store[session_id]

    return session_data


@app.post("/api/auth/credentials")
async def authenticate_credentials(credentials: BrokerCredentials , request:Request ,x_plugin_api_key: str = Header(None),x_forwarded_user: str = Header(None)):
    """
    Step 1: Accept and validate broker credentials.
    Returns session_id for next step.
    """
# verify_plugin_key(x_plugin_api_key)
    if not x_forwarded_user:
        raise HTTPException(status_code=400, detail="Missing X-Forwarded-User header")
    if not x_forwarded_user:
        raise HTTPException(status_code=400, detail="Missing X-Forwarded-User header")
    try:
        # Generate session ID
        session_id = f"session_{datetime.now().strftime('%Y%m%d%H%M%S')}_{os.urandom(4).hex()}"
        # user_id = request.state.user_id
        # Store credentials temporarily
        sessions_store[session_id] = {
            "session_id": session_id,
            # "user_id": user_id,
            "user_id": x_forwarded_user,
            "api_key": credentials.api_key,
            "client_code": credentials.client_code,
            "password": credentials.password,
            "created_at": datetime.now().isoformat(),
            "status": "credentials_received"
        }
        await persist_session_state(session_id)
        
        return JSONResponse(
            status_code=200,
            content={
                "success": True,
                "session_id": session_id,
                "message": "Credentials received. Please provide TOTP.",
                "requires_totp": True
            }
        )
        
    except Exception as e:
        raise HTTPException(status_code=400, detail=f"Credentials validation failed: {str(e)}")



@app.post("/api/auth/totp")
async def authenticate_totp(totp_req: TOTPRequest , x_plugin_api_key: str = Header(None)):
    """
    Step 2: Complete authentication with TOTP.
    Establishes broker connection and returns account info.
    """
# verify_plugin_key(x_plugin_api_key)
    print(
    "PID:", os.getpid(),
    "Thread:", threading.current_thread().name,
    "sessions_store_keys:", list(sessions_store.keys())
)
    session_id = totp_req.session_id
    
    # Use robust session retrieval
    session_data = await get_or_restore_session(session_id)
            
    if not session_data:
        raise HTTPException(status_code=404, detail="Session not found or expired")

    # Validate credentials exist before using them
    missing = [k for k in ("api_key", "client_code", "password") if not session_data.get(k)]
    if missing:
        raise HTTPException(
            status_code=400,
            detail=f"Missing credential fields in session ({', '.join(missing)}). Please re-enter credentials."
        )
    
    try:
        # logger.info(f"[{session_id}] Starting TOTP authentication")
        # logger.info(f"[{session_id}] Session status: {session_data.get('status')}")
        
        # Step 1: Set environment variables
        logger.info(f"[{session_id}] Setting environment variables...")
        os.environ["ANGEL_API_KEY"] = session_data["api_key"]
        os.environ["ANGEL_CLIENT_CODE"] = session_data["client_code"]
        os.environ["ANGEL_PASSWORD"] = session_data["password"]
        os.environ["ANGEL_TOTP"] = totp_req.totp or ""
        logger.info(f"[{session_id}] Environment variables set successfully")
        
        # Step 2: Create broker connector
        logger.info(f"[{session_id}] Creating BrokerConnector instance...")
        broker = BrokerConnector(require_totp=True)
        logger.info(f"[{session_id}] BrokerConnector created successfully")
        
        # Step 3: Get session from broker
        logger.info(f"[{session_id}] Calling broker.get_session()...")
        broker_session = broker.get_session()
        print("broker session in authenticate totp " , broker_session)
        logger.info(f"[{session_id}] broker_session received: {type(broker_session)}")
        logger.info(f"[{session_id}] broker_session keys: {list(broker_session.keys()) if isinstance(broker_session, dict) else 'Not a dict'}")
        

        

        if not broker_session or "token" not in broker_session:
            logger.error(f"[{session_id}] broker_session invalid: {broker_session}")
            raise Exception("Failed to establish broker session")
        logger.info(f"[{session_id}] broker_session validated successfully")
        
        # Step 4: Get account balance
        logger.info(f"[{session_id}] Calling broker.get_account_balance()...")
        balance_resp = broker.get_account_balance(broker_session)
        logger.info(f"[{session_id}] balance_resp received: {type(balance_resp)}")
        logger.info(f"[{session_id}] balance_resp: {balance_resp}")
        print("broker object is ",broker)
        free_cash = None
        if isinstance(balance_resp, dict) and balance_resp.get("status") == "success":
            free_cash = balance_resp.get("free_cash")
            logger.info(f"[{session_id}] free_cash from response: {free_cash}")
            if free_cash is None:
                logger.info(f"[{session_id}] Guessing free_cash from response...")
                free_cash = guess_free_cash_from_resp(balance_resp)
                logger.info(f"[{session_id}] Guessed free_cash: {free_cash}")
        else:
            logger.warning(f"[{session_id}] balance_resp not successful or not dict")
        
        # Step 5: Update session store
        logger.info(f"[{session_id}] Updating session store...")
        sessions_store[session_id].update({
            "status": "authenticated",
            "broker": broker,
            "broker_session": broker_session,
            "free_cash": free_cash,
            "authenticated_at": datetime.now().isoformat()
        })
        logger.info(f"[{session_id}] Session store updated")
        
        
        # Step 6: Persist to DB
        print("saving data in db using persist to db")
        logger.info(f"[{session_id}] Persisting session state to DB...")
        await persist_session_state (session_id)
        logger.info(f"[{session_id}] Session state persisted")
        
        # Step 7: Clean up env variables
        print("cleaning up env variables")
        logger.info(f"[{session_id}] Cleaning up environment variables...")
        for key in ["ANGEL_API_KEY", "ANGEL_CLIENT_CODE", "ANGEL_PASSWORD", "ANGEL_TOTP"]:
            if key in os.environ:
                del os.environ[key]
        logger.info(f"[{session_id}] Environment variables cleaned up")
        
        logger.info(f"[{session_id}] TOTP authentication completed successfully")

        # ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬ ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¦ HARD persist authenticated state (do NOT rely on persist_session_state)
        await persist_session_metadata(
            session_id,
            {
                "status": "authenticated",
                "authenticated_at": datetime.utcnow(),
                "free_cash": free_cash,
                "broker_session": {
                    "user": broker_session.get("user"),
                    "token": _encrypt_val(broker_session.get("token")),
                    "refresh_token": _encrypt_val(broker_session.get("refresh_token")),
                    "feed_token": _encrypt_val(broker_session.get("feed_token")),
                }
            }
        )

        db_session = fetch_session_from_db(session_id=session_id)
        print(db_session)

        return JSONResponse(
            status_code=200,
            content={
                "success": True,
                "session_id": session_id,
                "message": "Authentication successful",
                "account_info": {
                    "user": broker_session.get("user"),
                    "free_cash": free_cash,
                    "balance_details": balance_resp if isinstance(balance_resp, dict) else None
                },
                "free_cash": free_cash,
                # "broker_session": broker_session
            }
        )
        
    except Exception as e:
        logger.error(f"[{session_id}] Exception in TOTP authentication: {type(e).__name__}: {str(e)}", exc_info=True)
        
        # Clean up env variables on error
        for key in ["ANGEL_API_KEY", "ANGEL_CLIENT_CODE", "ANGEL_PASSWORD", "ANGEL_TOTP"]:
            if key in os.environ:
                del os.environ[key]
        
        raise HTTPException(status_code=401, detail=f"Authentication failed: {str(e)}")


